from collections import defaultdict
import heapq
from typing import List


class Solution:

    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        small = []  # max-heap (stores negated values)
        large = []  # min-heap
        delayed = defaultdict(int)

        small_size = 0
        large_size = 0

        def prune(heap: list, is_small: bool):
            while heap:
                val = -heap[0] if is_small else heap[0]
                if delayed[val] > 0:
                    delayed[val] -= 1
                    heapq.heappop(heap)
                else:
                    break

        def add_num(num: int):
            nonlocal small_size, large_size
            if not small or num <= -small[0]:
                heapq.heappush(small, -num)
                small_size += 1
            else:
                heapq.heappush(large, num)
                large_size += 1
            rebalance()

        def remove_num(num: int):
            nonlocal small_size, large_size
            delayed[num] += 1
            if num <= -small[0]:
                small_size -= 1
                if num == -small[0]:
                    prune(small, True)
            else:
                large_size -= 1
                if large and num == large[0]:
                    prune(large, False)
            rebalance()

        def rebalance():
            nonlocal small_size, large_size
            # small should have (k + 1) // 2 elements
            # large should have k // 2 elements
            target_small = (k + 1) // 2
            while small_size > target_small:
                prune(small, True)
                val = -heapq.heappop(small)
                heapq.heappush(large, val)
                small_size -= 1
                large_size += 1
                prune(small, True)

            while small_size < target_small:
                prune(large, False)
                val = heapq.heappop(large)
                heapq.heappush(small, -val)
                small_size += 1
                large_size -= 1
                prune(large, False)

        def get_median() -> float:
            prune(small, True)
            prune(large, False)
            if k % 2 == 1:
                return float(-small[0])
            else:
                return (-small[0] + large[0]) / 2.0

        for i in range(k):
            add_num(nums[i])

        ans = [get_median()]

        for i in range(k, len(nums)):
            add_num(nums[i])
            remove_num(nums[i - k])
            ans.append(get_median())

        return ans
