            if t[-1] == "0":
                return [t]
            return [t] + [t[:j] + "." + t[j:] for j in range(1, n)]

        ans = []
        for i in range(1, len(digits)):
            left_part = digits[:i]
            right_part = digits[i:]
            for x in get_valid(left_part):
                for y in get_valid(right_part):
                    ans.append(f"({x}, {y})")

