    def numFactoredBinaryTrees(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        arr.sort()
        dp = {}
        for i, x in enumerate(arr):
            ways = 1
            for j in range(i):
                left = arr[j]
                if left * left > x:
                    break
                if x % left == 0:
                    right = x // left
                    if right in dp:
                        if left == right:
                            ways = (ways + dp[left] * dp[right]) % MOD
                        else:
                            ways = (ways + 2 * dp[left] * dp[right]) % MOD
