from collections import deque

class MKAverage:

    def __init__(self, m: int, k: int):
        self.m = m
        self.k = k
        self.queue = deque()
        self.max_val = 100000
        self.bit_cnt = [0] * (self.max_val + 1)
        self.bit_sum = [0] * (self.max_val + 1)

    def _add(self, x: int, val: int) -> None:
        cnt_delta = val
        sum_delta = x * val
        i = x
        while i <= self.max_val:
            self.bit_cnt[i] += cnt_delta
            self.bit_sum[i] += sum_delta
            i += i & (-i)

    def _get_prefix_sum(self, r: int) -> int:
        if r == 0:
            return 0
        idx = 0
        cur_cnt = 0
        cur_sum = 0
        for i in range(16, -1, -1):
            next_idx = idx + (1 << i)
            if next_idx <= self.max_val and cur_cnt + self.bit_cnt[next_idx] < r:
                cur_cnt += self.bit_cnt[next_idx]
                cur_sum += self.bit_sum[next_idx]
                idx = next_idx
        return cur_sum + (r - cur_cnt) * (idx + 1)

    def addElement(self, num: int) -> None:
        self.queue.append(num)
        self._add(num, 1)
        if len(self.queue) > self.m:
            old = self.queue.popleft()
            self._add(old, -1)

    def calculateMKAverage(self) -> int:
        if len(self.queue) < self.m:
            return -1
        sum_total = self._get_prefix_sum(self.m - self.k) - self._get_prefix_sum(self.k)
        return sum_total // (self.m - 2 * self.k)
