class Solution:
    def largestMagicSquare(self, grid: list[list[int]]) -> int:
        m, n = len(grid), len(grid[0])

        row_pref = [[0] * (n + 1) for _ in range(m)]
        col_pref = [[0] * n for _ in range(m + 1)]

        for r in range(m):
            for c in range(n):
                row_pref[r][c + 1] = row_pref[r][c] + grid[r][c]
                col_pref[r + 1][c] = col_pref[r][c] + grid[r][c]

        for k in range(min(m, n), 1, -1):
            for r in range(m - k + 1):
                for c in range(n - k + 1):
                    target = row_pref[r][c + k] - row_pref[r][c]

                    # Check remaining rows
                    if any(row_pref[r + i][c + k] - row_pref[r + i][c] != target for i in range(1, k)):
                        continue

                    # Check columns
                    if any(col_pref[r + k][c + j] - col_pref[r][c + j] != target for j in range(k)):
                        continue

                    # Check main diagonal
                    if sum(grid[r + d][c + d] for d in range(k)) != target:
                        continue

                    # Check anti-diagonal
                    if sum(grid[r + d][c + k - 1 - d] for d in range(k)) != target:
                        continue

                    return k

        return 1
