from typing import List


class Solution:
    def minCost(
        self, maxTime: int, edges: List[List[int]], passingFees: List[int]
    ) -> int:
        n = len(passingFees)
        adj = [[] for _ in range(n)]
        for u, v, t in edges:
            adj[u].append((v, t))
            adj[v].append((u, t))

        # min_time[u] stores the minimum time to reach node u popped so far.
        min_time = [float("inf")] * n

        # Priority queue stores (cost, u, time)
        pq = [(passingFees[0], 0, 0)]

        while pq:
            cost, u, t = heapq.heappop(pq)

            if u == n - 1:
                return cost

            if t >= min_time[u]:
                continue
            min_time[u] = t

            for v, edge_time in adj[u]:
                nt = t + edge_time
                if nt <= maxTime and nt < min_time[v]:
                    heapq.heappush(pq, (cost + passingFees[v], v, nt))

        return -1
