class Solution:
    def minStickers(self, stickers: List[str], target: str) -> int:
        n = len(target)
        target_counts = Counter(target)

        # Preprocess stickers to only retain characters present in target
        processed_stickers = []
        for sticker in stickers:
            count = Counter(sticker)
            filtered = {c: count[c] for c in count if c in target_counts}
            if filtered:
                processed_stickers.append(filtered)

        # BFS
        queue = deque([(0, 0)])
        visited = [False] * (1 << n)
        visited[0] = True

        while queue:
            mask, steps = queue.popleft()

            if mask == (1 << n) - 1:
                return steps

            # Find the first unset bit
            first_unset = 0
            while (mask & (1 << first_unset)) != 0:
                first_unset += 1

            target_char = target[first_unset]

            for sticker in processed_stickers:
                if target_char not in sticker:
                    continue

                next_mask = mask
                rem_counts = sticker.copy()
                for j in range(n):
                    if not (next_mask & (1 << j)) and rem_counts.get(target[j], 0) > 0:
                        rem_counts[target[j]] -= 1
                        next_mask |= (1 << j)

                if not visited[next_mask]:
                    visited[next_mask] = True
                    queue.append((next_mask, steps + 1))

        return -1
